async function main(ctx) {
  const input = ctx.input || {};
  const tableIdOrSlug = typeof input.tableIdOrSlug === 'string' ? input.tableIdOrSlug.trim() : '';
  if (!tableIdOrSlug) throw new Error('tableIdOrSlug is required');

  const title = typeof input.title === 'string' ? input.title.trim() : '';
  const description = typeof input.description === 'string' ? input.description.trim() : '';

  return {
    widgetType: 'table_card',
    props: {
      id: 'table:' + tableIdOrSlug,
      tableIdOrSlug,
      ...(title ? { title } : {}),
      ...(description ? { description } : {})
    }
  };
}
